// Проверка подписи Prodamus (HMAC-SHA256) по схеме их Hmac SDK.
// Секрет ТОЛЬКО из $env.PRODAMUS_SECRET (не хардкод). Значения подписи/секрета НЕ логировать.
//
// Схема Prodamus Hmac (PHP): array_walk_recursive -> strval ВСЕХ значений; рекурсивный ksort;
// затем json_encode($data, JSON_UNESCAPED_UNICODE) (НЕ query-string!); hash_hmac('sha256', json, key).
// json_encode по умолчанию ЭКРАНИРУЕТ '/' как '\/' (JSON_UNESCAPED_SLASHES не выставлен) — повторяем.
// !! ОБЯЗАТЕЛЬНО сверить calc==Sign на реальном тест-уведомлении. Если не сходится, искать расхождение в:
//    (1) форма products[] — массив (PHP numeric list -> [...]) против объекта {"0":..} у n8n multipart-парсера;
//    (2) какие поля подписываются (возможно без headers, только тело; возможно иное множество полей);
//    (3) экранирование '/'. Правка — здесь, до перехода в строгий режим.
const crypto = require('crypto');
const SECRET  = $env.PRODAMUS_SECRET || '';
const shop    = $('Shop').item.json || {};
const body    = shop.body || {};
const headers = shop.headers || {};
const sign    = String(headers['sign'] || headers['Sign'] || '').toLowerCase();

function toStrDeep(v){
  if (Array.isArray(v)) return v.map(toStrDeep);
  if (v && typeof v === 'object'){ const o = {}; for (const k of Object.keys(v)) o[k] = toStrDeep(v[k]); return o; }
  if (v === true)  return '1';           // PHP strval(true)='1'
  if (v === false) return '';            // PHP strval(false)=''
  if (v === null || v === undefined) return '';
  return String(v);
}
function ksortDeep(v){
  if (Array.isArray(v)) return v.map(ksortDeep);   // список: порядок сохраняется (числовые ключи)
  if (v && typeof v === 'object'){ const o = {}; for (const k of Object.keys(v).sort()) o[k] = ksortDeep(v[k]); return o; }
  return v;
}
const prepared = ksortDeep(toStrDeep(body));
const jsonStr  = JSON.stringify(prepared).replace(/\//g, '\\/');   // '/' -> '\/' как PHP json_encode
const calc     = SECRET ? crypto.createHmac('sha256', SECRET).update(jsonStr, 'utf8').digest('hex') : '';
return [{ json: { sig_ok: !!calc && calc === sign, sign_present: !!sign } }];
